// The audio worklet and the song clock in real browsers (the `browser` project in
// vitest.config.ts). The fixture is pb-fixture-01.mod, a module (a song file made in a
// music tracker) generated by tools/make-fixture-mod.ts.

import { analyze, loadOpenMpt } from '@game/analysis';
import fixtureUrl from '@game/analysis/fixtures/pb-fixture-01.mod?url';
import { CHUNK_FRAMES, SAMPLE_RATE } from '@game/core';
import { describe, expect, it } from 'vitest';
import { createAudioPlayer, type AudioPlayer, type PositionMessage } from '../../src/audio/index.ts';

const QUANTUM = 128;

async function fixture(): Promise<Uint8Array> {
  const response = await fetch(fixtureUrl);
  if (!response.ok) throw new Error(`fetch ${fixtureUrl}: ${response.status}`);
  return new Uint8Array(await response.arrayBuffer());
}

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/**
 * Suspends `context` after each render quantum until `started` resolves. Offline rendering
 * doesn't wait for messages in flight: after the analysis has held the main thread for a few
 * seconds, WebKit rendered all 50 s of silence before the worklet saw 'start'. Firefox (159)
 * has no OfflineAudioContext.suspend, and there the message arrives in time without it.
 */
function holdUntil(context: OfflineAudioContext, started: Promise<void>): void {
  if (typeof context.suspend !== 'function') return;
  let done = false;
  void started.then(() => (done = true));
  const hold = (k: number): void => {
    void context.suspend((k * QUANTUM) / SAMPLE_RATE).then(async () => {
      await sleep(1);
      if (!done) hold(k + 1);
      await context.resume();
    });
  };
  hold(1);
}

describe('libopenmpt worklet', () => {
  it('reports row positions that match LevelData', async () => {
    const bytes = await fixture();
    const level = analyze(await loadOpenMpt(), bytes);

    // An OfflineAudioContext renders as fast as it can, with the same quantum and
    // currentFrame rules as a live context.
    const context = new OfflineAudioContext(2, SAMPLE_RATE * 50, SAMPLE_RATE);
    const player = await createAudioPlayer({ context });
    await player.load(bytes);
    const rows: number[] = [];
    const positions: PositionMessage[] = [];
    player.onPosition = (p) => {
      positions.push(p);
      rows.push(...p.rows);
    };
    const ended = new Promise<number>((resolve) => {
      player.onEnded = resolve;
    });
    const started = player.start();
    holdUntil(context, started);
    await context.startRendering();
    await started;
    const songFrames = await ended;

    expect(level.rows.timeSamples.length).toBe(449);
    expect(rows.length / 3).toBe(level.rows.timeSamples.length);
    let worst = 0;
    for (let i = 0; i < level.rows.timeSamples.length; i++) {
      expect([rows[i * 3 + 1], rows[i * 3 + 2]]).toEqual([level.rows.order[i], level.rows.row[i]]);
      worst = Math.max(worst, Math.abs(rows[i * 3]! - level.rows.timeSamples[i]!));
    }
    console.log(`row time difference, worklet vs LevelData: at most ${worst} frames`);
    expect(worst).toBeLessThanOrEqual(CHUNK_FRAMES + QUANTUM);
    expect(Math.abs(songFrames - level.totalSamples)).toBeLessThanOrEqual(QUANTUM);

    // No quantum was skipped: each message's context frame minus its song frame is the anchor.
    const anchor = Math.round(player.startTime! * SAMPLE_RATE);
    for (const p of positions) expect(p.contextFrame - p.songFrames).toBe(anchor);
    await player.close();
  }, 120_000);
});

describe('song clock', () => {
  async function playing(): Promise<AudioPlayer> {
    const player = await createAudioPlayer();
    await player.load(await fixture());
    await player.start();
    return player;
  }

  it('advances while playing and tracks the worklet', async () => {
    const player = await playing();
    const leads: number[] = [];
    player.onPosition = (p) => {
      // The clock minus the position the message describes, both without latency or offset.
      const graph = player.context.currentTime * SAMPLE_RATE - player.startTime! * SAMPLE_RATE;
      leads.push(graph - p.songFrames);
    };
    const t0 = player.songTimeSamples();
    await sleep(500);
    const t1 = player.songTimeSamples();
    expect(t1 - t0).toBeGreaterThan(SAMPLE_RATE * 0.3);
    expect(t1 - t0).toBeLessThan(SAMPLE_RATE * 0.8);
    expect(leads.length).toBeGreaterThan(3);
    const min = Math.min(...leads);
    const max = Math.max(...leads);
    console.log(
      `latency ${(player.latency * 1000).toFixed(1)} ms; context time minus reported position on receipt: ` +
        `${min} to ${max} frames (${((min / SAMPLE_RATE) * 1000).toFixed(1)} to ${((max / SAMPLE_RATE) * 1000).toFixed(1)} ms)`,
    );
    // The message describes a quantum the graph has finished, and it arrives well within
    // 100 ms. The spec has currentTime advance one render quantum at a time but doesn't say
    // how soon the main thread sees each step: Chromium and WebKit are at or past the
    // message, Firefox (159, on a PulseAudio null sink) up to two quanta behind it. The clock
    // only measures currentTime against the anchor, so that lag is 5.3 ms early, not an error.
    expect(min).toBeGreaterThanOrEqual(-2 * QUANTUM);
    expect(max).toBeLessThan(SAMPLE_RATE * 0.1);
    await player.close();
  }, 30_000);

  it('stops while paused and continues without a jump', async () => {
    const player = await playing();
    await sleep(200);
    await player.pause();
    expect(player.state).toBe('paused');
    const paused = player.songTimeSamples();
    await sleep(300);
    expect(player.songTimeSamples()).toBe(paused);
    await player.resume();
    const resumed = player.songTimeSamples();
    expect(resumed).toBeGreaterThanOrEqual(paused);
    expect(resumed - paused).toBeLessThan(SAMPLE_RATE * 0.05);
    await sleep(300);
    expect(player.songTimeSamples() - paused).toBeGreaterThan(SAMPLE_RATE * 0.2);
    await player.close();
  }, 30_000);

  it('restarts from the beginning', async () => {
    const player = await playing();
    await sleep(300);
    expect(player.songTimeSamples()).toBeGreaterThan(SAMPLE_RATE * 0.2);
    await player.start();
    expect(player.songTimeSamples()).toBeLessThan(SAMPLE_RATE * 0.05);
    await player.close();
  }, 30_000);
});
